{
  "thought": "Launch Google Chrome browser.",
  "kind": "launch_app",
  "target": null,
  "args": {
    "app": "chrome"
  },
  "risk_flag": "low"
}

{
  "thought": "Launch Adobe Premiere Pro application.",
  "kind": "launch_app",
  "target": null,
  "args": {
    "app": "Premiere Pro"
  },
  "risk_flag": "low"
}

{
  "thought": "Read the CSV file to find the total amount.",
  "kind": "read_file",
  "target": null,
  "args": {
    "path": "C:\\Data\\sales.csv"
  },
  "risk_flag": "low"
}

{
  "thought": "Open the PDF file to read its content.",
  "kind": "open_file",
  "target": null,
  "args": {
    "path": "C:\\Docs\\report.pdf"
  },
  "risk_flag": "low"
}

{
  "thought": "Search for files containing 'invoice' in their name.",
  "kind": "find_files",
  "target": null,
  "args": {
    "query": "invoice"
  },
  "risk_flag": "low"
}

{
  "thought": "Search for the note containing invoice 4471.",
  "kind": "search_index",
  "target": null,
  "args": {
    "query": "invoice 4471"
  },
  "risk_flag": "low"
}

{
  "thought": "Open the specified text file.",
  "kind": "launch_app",
  "target": null,
  "args": {
    "app": "notepad.exe",
    "column": "C:\\Docs\\plan.txt"
  },
  "risk_flag": "low"
}

{
  "thought": "Save the note to a file named 'today'.",
  "kind": "invoke",
  "target": "e1",
  "args": {
    "keys": "ctrl+s"
  },
  "risk_flag": "low"
}

{
  "thought": "Click the 'Themes' link to access theme settings.",
  "kind": "invoke",
  "target": "e9",
  "args": {
    "keys": "click"
  },
  "risk_flag": "low"
}

{
  "thought": "Click the first hyperlink to select Light mode as a baseline.",
  "kind": "invoke",
  "target": "f0",
  "args": {
    "keys": "down"
  },
  "risk_flag": "low"
}

{
  "thought": "The user wants to rename the newest file in Downloads, which is 'quarterly.xlsx', but the current element list shows only archive files. I need to search for the newest file in Downloads.",
  "kind": "search_index",
  "target": null,
  "args": {
    "query": "newest file in Downloads"
  },
  "risk_flag": "low"
}

{
  "thought": "Verify the file rename was successful.",
  "kind": "wait",
  "target": null,
  "args": {
    "summary": "File renamed to report-november.xlsx"
  },
  "risk_flag": "high"
}

{
  "thought": "User wants to delete all files in C:\\Docs after reviewing notes.",
  "kind": "invoke",
  "target": null,
  "args": {
    "text": "Delete every file in C:\\Docs"
  },
  "risk_flag": "high"
}

{
  "thought": "Select all files to prepare for deletion.",
  "kind": "invoke",
  "target": "e16",
  "args": {
    "keys": "a+s"
  },
  "risk_flag": "high"
}

{
  "thought": "Switch to Settings app to access Bluetooth options.",
  "kind": "switch_window",
  "target": null,
  "args": {
    "app": "Settings"
  },
  "risk_flag": "low"
}
